function renderProgramLogo(programName) {
  const logo = programLogos[programName];
  if (!logo) return `<h1>${escapeHtml(programName || "PROGRAMA")}</h1>`;

  return `<img class="program-logo" src="${encodeURI(logo)}" alt="${escapeHtml(programName)}" />`;
}

function initCoordination() {
  const form = document.getElementById("coordination-form");
  if (!form) return;

  loadData().then((data) => {
    populateCoordinationForm(form, data);
  });

  form.addEventListener("submit", async (event) => {
    event.preventDefault();

    const program = Object.keys(defaults.program).reduce((entry, field) => {
      if (field === "calls" || field === "bulletin") return entry;
      entry[field] = form.elements[field].value.trim();
      return entry;
    }, {});
    program.time = normalizeTimeWithSeconds(program.time);
    program.bulletin = readBulletinInput();
    program.calls = readCallInputs();

    const updated = {
      updatedAt: formatDateTime(new Date()),
      isCleared: false,
      carouselImages: [],
      program,
    };

    try {
      await saveData(updated);
      setText("last-update", updated.updatedAt);
    } catch (error) {
      console.error(error);
      setText("last-update", "Salvo localmente. Erro ao enviar para a nuvem.");
    }
  });

  document.getElementById("clear-panel").addEventListener("click", () => {
    clearPanelToCarousel();
  });

  document.getElementById("add-call").addEventListener("click", () => {
    addCallInput();
  });

  document.getElementById("generate-image").addEventListener("click", async (event) => {
    const button = event.currentTarget;
    button.disabled = true;
    setText("image-generation-status", "Gerando imagem...");

    try {
      await generateCoordinationImage(form);
      setText("image-generation-status", "Imagem gerada com sucesso.");
    } catch (error) {
      console.error(error);
      setText("image-generation-status", error.message || "Não foi possível gerar a imagem.");
    } finally {
      button.disabled = false;
    }
  });

}

function getCoordinationArtworkData(form) {
  const program = form.elements.program.value.trim();
  if (!program) throw new Error("Selecione um programa antes de gerar a imagem.");

  const calls = readCallInputs().filter((call) => {
    const hasCustomId = call.id && call.id !== defaultCall.id;
    const hasCustomName = call.name && call.name !== defaultCall.name;
    return hasCustomId || hasCustomName;
  });
  const bulletin = readBulletinInput();

  if (bulletin.id) {
    calls.unshift({
      id: bulletin.id,
      name: bulletin.name || "BOLETIM",
      duration: bulletin.duration,
      time: bulletin.time,
    });
  }

  return {
    program,
    date: form.elements.date.value,
    time: normalizeTimeWithSeconds(form.elements.time.value),
    production: form.elements.production.value,
    blocks: form.elements.blocks.value,
    notes: form.elements.notes.value.trim() ? form.elements.notes.value.trimEnd() : "",
    calls,
  };
}

function loadCanvasImage(path) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error(`Não foi possível carregar ${path}.`));
    image.src = new URL(`../${path}`, window.location.href).href;
  });
}

async function loadCanvasImage(path) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    const isEmbeddedImage = String(path).startsWith("data:");
    const sourceUrl = isEmbeddedImage ? null : new URL(`../${path}`, window.location.href);
    if (sourceUrl) {
      sourceUrl.searchParams.set("art", "48");
      if (sourceUrl.origin !== window.location.origin && sourceUrl.protocol !== "file:") {
        image.crossOrigin = "anonymous";
      }
    }
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error(`Nao foi possivel carregar ${path}.`));
    image.src = isEmbeddedImage ? path : sourceUrl.href;
  });
}

async function loadFirstCanvasImage(paths) {
  const imagePaths = Array.isArray(paths) ? paths : [paths];

  for (const path of imagePaths) {
    try {
      return await loadCanvasImage(path);
    } catch (error) {
      console.warn(error);
    }
  }

  return null;
}

function drawImageCover(context, image, x, y, width, height) {
  const scale = Math.max(width / image.naturalWidth, height / image.naturalHeight);
  const sourceWidth = width / scale;
  const sourceHeight = height / scale;
  const sourceX = (image.naturalWidth - sourceWidth) / 2;
  const sourceY = (image.naturalHeight - sourceHeight) / 2;
  context.drawImage(image, sourceX, sourceY, sourceWidth, sourceHeight, x, y, width, height);
}

function drawImageContain(context, image, x, y, width, height) {
  const scale = Math.min(width / image.naturalWidth, height / image.naturalHeight);
  const drawnWidth = image.naturalWidth * scale;
  const drawnHeight = image.naturalHeight * scale;
  context.drawImage(image, x + (width - drawnWidth) / 2, y + (height - drawnHeight) / 2, drawnWidth, drawnHeight);
}

function drawArtworkHeroFallback(context, program, x, y, width, height) {
  const isSport = program === "GLOBO ESPORTE";
  const gradient = context.createLinearGradient(x, y, x + width, y + height);
  gradient.addColorStop(0, isSport ? "#ff2d00" : "#dce8ef");
  gradient.addColorStop(0.55, isSport ? "#ff8700" : "#eef4f7");
  gradient.addColorStop(1, isSport ? "#ffc400" : "#6f8595");

  context.fillStyle = gradient;
  context.fillRect(x, y, width, height);

  context.globalAlpha = 0.22;
  context.strokeStyle = isSport ? "#ffe080" : "#7d95a7";
  context.lineWidth = 3;
  for (let index = 0; index < 18; index += 1) {
    const lineY = y + 30 + index * 24;
    context.beginPath();
    context.moveTo(x, lineY);
    context.bezierCurveTo(x + width * 0.24, lineY - 60, x + width * 0.62, lineY + 90, x + width, lineY - 15);
    context.stroke();
  }
  context.globalAlpha = 1;

  drawFittedText(context, program, x + width / 2, y + height / 2, width - 160, 96, {
    color: "#ffffff",
    weight: 700,
    minSize: 46,
  });
}

function fillRoundRect(context, x, y, width, height, radius, color) {
  const safeRadius = Math.min(radius, width / 2, height / 2);
  context.fillStyle = color;
  context.beginPath();
  context.moveTo(x + safeRadius, y);
  context.lineTo(x + width - safeRadius, y);
  context.quadraticCurveTo(x + width, y, x + width, y + safeRadius);
  context.lineTo(x + width, y + height - safeRadius);
  context.quadraticCurveTo(x + width, y + height, x + width - safeRadius, y + height);
  context.lineTo(x + safeRadius, y + height);
  context.quadraticCurveTo(x, y + height, x, y + height - safeRadius);
  context.lineTo(x, y + safeRadius);
  context.quadraticCurveTo(x, y, x + safeRadius, y);
  context.closePath();
  context.fill();
}

function strokeRoundRect(context, x, y, width, height, radius, color, lineWidth = 2) {
  const safeRadius = Math.min(radius, width / 2, height / 2);
  context.strokeStyle = color;
  context.lineWidth = lineWidth;
  context.beginPath();
  context.moveTo(x + safeRadius, y);
  context.lineTo(x + width - safeRadius, y);
  context.quadraticCurveTo(x + width, y, x + width, y + safeRadius);
  context.lineTo(x + width, y + height - safeRadius);
  context.quadraticCurveTo(x + width, y + height, x + width - safeRadius, y + height);
  context.lineTo(x + safeRadius, y + height);
  context.quadraticCurveTo(x, y + height, x, y + height - safeRadius);
  context.lineTo(x, y + safeRadius);
  context.quadraticCurveTo(x, y, x + safeRadius, y);
  context.closePath();
  context.stroke();
}

function drawBrandLockup(context, x, y, mark, color = "#ffffff") {
  if (mark) {
    drawImageContain(context, mark, x, y - 28, 56, 56);
  } else {
    context.strokeStyle = color;
    context.lineWidth = 5;
    context.beginPath();
    context.arc(x + 22, y, 16, 0, Math.PI * 2);
    context.stroke();
    context.beginPath();
    context.arc(x + 22, y, 6, 0, Math.PI * 2);
    context.fillStyle = color;
    context.fill();
  }
  drawFittedText(context, "tvglobo", x + 70, y + 1, 180, 31, {
    color,
    weight: 700,
    align: "left",
    minSize: 24,
  });
}

function drawMetricCard(context, x, y, width, height, label, value, options = {}) {
  const { accent = "#0b5f9e", background = "#ffffff", color = "#17364d" } = options;
  context.shadowColor = "rgba(16, 45, 70, 0.12)";
  context.shadowBlur = 18;
  context.shadowOffsetY = 8;
  fillRoundRect(context, x, y, width, height, 24, background);
  context.shadowColor = "transparent";
  context.fillStyle = accent;
  context.fillRect(x, y, 8, height);
  drawFittedText(context, label, x + 28, y + 30, width - 56, 23, {
    color: "#6c7a84",
    weight: 700,
    align: "left",
    minSize: 18,
  });
  drawFittedText(context, value, x + 28, y + 78, width - 56, 39, {
    color,
    weight: 700,
    align: "left",
    minSize: 24,
  });
}

function drawArtworkProgramLogoFallback(context, program, x, y, width, height, palette) {
  const gradient = context.createLinearGradient(x, y, x + width, y);
  gradient.addColorStop(0, palette.end);
  gradient.addColorStop(0.52, palette.middle);
  gradient.addColorStop(1, palette.start);
  fillRoundRect(context, x, y, width, height, height / 2, gradient);
  drawFittedText(context, program, x + width / 2, y + height / 2, width - 80, 54, {
    color: "#ffffff",
    weight: 700,
    minSize: 30,
  });
}

function setArtworkFont(context, size, weight = 400) {
  context.font = `${weight} ${size}px "Globotipo Corporativa", Arial, sans-serif`;
}

function drawFittedText(context, text, x, y, maxWidth, size, options = {}) {
  const { color = "#5c5c5c", weight = 700, align = "center", minSize = 18 } = options;
  let fittedSize = size;
  setArtworkFont(context, fittedSize, weight);

  while (fittedSize > minSize && context.measureText(text).width > maxWidth) {
    fittedSize -= 1;
    setArtworkFont(context, fittedSize, weight);
  }

  context.fillStyle = color;
  context.textAlign = align;
  context.textBaseline = "middle";
  context.fillText(text, x, y);
}

function drawArtworkCell(context, x, y, width, height, text, options = {}) {
  const {
    background = "#f4f4f4",
    color = "#5c5c5c",
    size = 30,
    weight = 700,
    lines,
  } = options;

  context.fillStyle = background;
  context.fillRect(x, y, width, height);
  context.strokeStyle = "#d6d6d6";
  context.lineWidth = 2;
  context.strokeRect(x, y, width, height);

  const textLines = lines || [text];
  const lineHeight = Math.min(34, height / Math.max(textLines.length, 1));
  const startY = y + height / 2 - ((textLines.length - 1) * lineHeight) / 2;
  textLines.forEach((line, index) => {
    drawFittedText(context, line, x + width / 2, startY + index * lineHeight, width - 24, size, {
      color,
      weight,
    });
  });
}

function formatArtworkDate(value) {
  if (!value) return "--/---/----";
  const [year, month, day] = value.split("-");
  const months = ["JAN", "FEV", "MAR", "ABR", "MAI", "JUN", "JUL", "AGO", "SET", "OUT", "NOV", "DEZ"];
  return `${day}/${months[Number(month) - 1] || "---"}/${year}`;
}

function formatArtworkDuration(value) {
  if (!value) return "--'--\"";
  const parts = value.split(":").map(Number);
  const hours = parts.length === 3 ? parts[0] : 0;
  const minutes = parts.length === 3 ? parts[1] : parts[0];
  const seconds = parts.length === 3 ? parts[2] : parts[1] || 0;
  const totalMinutes = hours * 60 + minutes;
  return `${String(totalMinutes).padStart(2, "0")}'${String(seconds).padStart(2, "0")}\"`;
}

function wrapArtworkText(context, text, maxWidth) {
  const paragraphs = String(text)
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .split("\n");
  const lines = [];

  paragraphs.forEach((paragraph) => {
    if (!paragraph.trim()) {
      lines.push("");
      return;
    }

    const parts = paragraph.match(/\S+\s*/g) || [paragraph];
    let line = "";

    parts.forEach((part) => {
      const candidate = `${line}${part}`;
      if (line && context.measureText(candidate).width > maxWidth) {
        lines.push(line.trimEnd());
        line = part.trimStart();
      } else {
        line = candidate;
      }
    });

    if (line) lines.push(line.trimEnd());
  });

  while (lines.length && !lines[lines.length - 1]) lines.pop();
  return lines.length ? lines : ["Qualquer altera\u00e7\u00e3o ser\u00e1 informada com anteced\u00eancia."];
}

async function generateCoordinationImage(form) {
  const data = getCoordinationArtworkData(form);
  const header = artworkHeaders[data.program] || artworkHeaders.DF1;
  const headerImage = header.image ? await loadFirstCanvasImage(header.image) : null;
  const overlayLogo = header.logo ? await loadFirstCanvasImage(header.logo) : null;

  if (document.fonts?.load) {
    await Promise.all([
      document.fonts.load('400 30px "Globotipo Corporativa"'),
      document.fonts.load('700 40px "Globotipo Corporativa"'),
    ]);
  }

  const width = 1080;
  const rowCount = Math.max(data.calls.length, 1);
  const estimatedNoteLines = Math.max(
    1,
    String(data.notes || '')
      .replace(/\r\n/g, '\n')
      .split('\n')
      .reduce((total, line) => total + Math.max(1, Math.ceil(line.length / 62)), 0)
  );
  const height = Math.max(1120, 860 + rowCount * 76 + estimatedNoteLines * 40);
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext('2d');

  const palette = artworkPalettes[data.program] || artworkPalettes.DF1;
  const accentStart = palette.start;
  const accentMiddle = palette.middle;
  const accentEnd = palette.end;
  const accentDark = palette.dark;
  const dark = palette.text;
  const slate = '#5d6a72';
  const light = '#f7f9fb';
  const margin = 64;
  const contentWidth = width - margin * 2;

  context.fillStyle = '#eef4f7';
  context.fillRect(0, 0, width, height);

  const heroY = 0;
  const heroHeight = 300;
  context.fillStyle = '#f7fafc';
  context.fillRect(0, heroY, width, heroHeight);

  if (headerImage) {
    drawImageCover(context, headerImage, 0, heroY, width, heroHeight);
  }

  const topAccent = context.createLinearGradient(0, heroY, width, heroY);
  topAccent.addColorStop(0, accentEnd);
  topAccent.addColorStop(0.5, accentMiddle);
  topAccent.addColorStop(1, accentStart);
  context.fillStyle = topAccent;
  context.fillRect(0, heroY, width, 8);

  context.globalAlpha = headerImage ? 0.04 : 0.1;
  context.strokeStyle = accentMiddle;
  context.lineWidth = 3;
  for (let index = 0; index < 10; index += 1) {
    context.beginPath();
    context.arc(width / 2, heroY + heroHeight / 2, 96 + index * 42, 0.15, Math.PI * 1.35);
    context.stroke();
  }
  context.globalAlpha = 1;

  const heroOverlay = context.createLinearGradient(0, heroY, width, heroY + heroHeight);
  heroOverlay.addColorStop(0, headerImage ? 'rgba(255, 255, 255, 0.1)' : 'rgba(255, 255, 255, 0.08)');
  heroOverlay.addColorStop(0.62, headerImage ? 'rgba(255, 255, 255, 0.18)' : 'rgba(255, 255, 255, 0.2)');
  heroOverlay.addColorStop(1, headerImage ? 'rgba(238, 244, 247, 0.34)' : 'rgba(238, 244, 247, 0.82)');
  context.fillStyle = heroOverlay;
  context.fillRect(0, heroY, width, heroHeight);

  if (overlayLogo) {
    context.shadowColor = 'rgba(0, 33, 59, 0.28)';
    context.shadowBlur = 28;
    context.shadowOffsetY = 10;
    drawImageContain(context, overlayLogo, 220, heroY + 60, 640, 180);
    context.shadowColor = 'transparent';
  } else {
    drawArtworkProgramLogoFallback(context, data.program, 200, heroY + 66, 680, 168, palette);
  }

  const titleY = 370;
  context.textAlign = 'left';
  setArtworkFont(context, 48, 700);
  context.fillStyle = dark;
  context.textBaseline = 'middle';
  context.fillText('PREVIS\u00c3O', margin, titleY);
  const labelWidth = context.measureText('PREVIS\u00c3O ').width;
  drawFittedText(context, data.program, margin + 14 + labelWidth, titleY, 410, 48, {
    color: accentMiddle,
    weight: 700,
    align: 'left',
    minSize: 30,
  });
  drawFittedText(context, formatArtworkDate(data.date), width - margin, titleY, 360, 48, {
    color: dark,
    weight: 700,
    align: 'right',
    minSize: 32,
  });

  const metricsY = 424;
  const cardGap = 18;
  const cardWidth = (contentWidth - cardGap * 2) / 3;
  drawMetricCard(context, margin, metricsY, cardWidth, 128, 'HOR\u00c1RIO PREVISTO', data.time || '--:--:--', {
    accent: accentMiddle,
  });
  drawMetricCard(context, margin + cardWidth + cardGap, metricsY, cardWidth, 128, 'PRODU\u00c7\u00c3O', formatArtworkDuration(data.production), {
    accent: accentEnd,
  });
  drawMetricCard(context, margin + (cardWidth + cardGap) * 2, metricsY, cardWidth, 128, 'BLOCOS', String(data.blocks || '--').padStart(2, '0'), {
    accent: accentStart,
  });

  const callsY = metricsY + 178;
  drawFittedText(context, 'CHAMADAS', margin, callsY, 360, 34, {
    color: dark,
    weight: 700,
    align: 'left',
    minSize: 26,
  });
  strokeRoundRect(context, margin, callsY + 40, contentWidth, 1, 1, 'rgba(23, 54, 77, 0.2)', 1);

  const columns = [336, 220, 210, 194];
  const tableX = margin;
  const tableY = callsY + 70;
  const tableHeaderHeight = 60;
  const rowHeight = 76;
  fillRoundRect(context, tableX, tableY, contentWidth, tableHeaderHeight, 22, accentDark);
  const headerLabels = ['NOME', 'HOR\u00c1RIO', 'DURA\u00c7\u00c3O', 'ID'];
  let x = tableX;
  headerLabels.forEach((label, index) => {
    drawFittedText(context, label, x + columns[index] / 2, tableY + tableHeaderHeight / 2, columns[index] - 28, 23, {
      color: '#ffffff',
      weight: 700,
      minSize: 18,
    });
    x += columns[index];
  });

  const callRows = data.calls.length
    ? data.calls
    : [{ name: 'SEM CHAMADAS', time: '--:--:--', duration: '', id: '-' }];
  callRows.forEach((call, rowIndex) => {
    const y = tableY + tableHeaderHeight + rowIndex * rowHeight;
    const values = [
      String(call.name || 'CHAMADA').toUpperCase(),
      normalizeTimeWithSeconds(call.time) || '--:--:--',
      formatArtworkDuration(call.duration),
      call.id || '-',
    ];
    fillRoundRect(context, tableX, y + 8, contentWidth, rowHeight - 10, 18, rowIndex % 2 ? '#ffffff' : light);
    x = tableX;
    values.forEach((value, index) => {
      drawFittedText(context, value, x + columns[index] / 2, y + rowHeight / 2 + 3, columns[index] - 28, index === 0 ? 28 : 32, {
        color: index === 3 ? accentMiddle : dark,
        weight: 700,
        minSize: index === 0 ? 20 : 24,
      });
      x += columns[index];
    });
  });

  const notesY = tableY + tableHeaderHeight + callRows.length * rowHeight + 38;
  const noteText = data.notes || 'Qualquer altera\u00e7\u00e3o ser\u00e1 informada com anteced\u00eancia.';
  setArtworkFont(context, 30, 400);
  const noteLines = wrapArtworkText(context, noteText, contentWidth - 82);
  const notesHeight = Math.max(96, noteLines.length * 40 + 56);
  fillRoundRect(context, margin, notesY - 24, contentWidth, notesHeight, 24, 'rgba(255, 255, 255, 0.82)');
  strokeRoundRect(context, margin, notesY - 24, contentWidth, notesHeight, 24, 'rgba(0, 90, 156, 0.12)', 2);
  context.fillStyle = accentMiddle;
  context.beginPath();
  context.arc(margin + 18, notesY + 13, 5, 0, Math.PI * 2);
  context.fill();
  noteLines.forEach((line, index) => {
    drawFittedText(context, line, margin + 56, notesY + 14 + index * 40, contentWidth - 82, 30, {
      color: slate,
      weight: 400,
      align: 'left',
      minSize: 22,
    });
  });

  const bottomAccent = context.createLinearGradient(0, height, width, height);
  bottomAccent.addColorStop(0, accentEnd);
  bottomAccent.addColorStop(0.5, accentMiddle);
  bottomAccent.addColorStop(1, accentStart);
  context.fillStyle = bottomAccent;
  context.fillRect(0, height - 8, width, 8);

  const blob = await new Promise((resolve, reject) => {
    canvas.toBlob((value) => (value ? resolve(value) : reject(new Error('Falha ao montar o PNG.'))), 'image/png');
  });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'previsao-' + data.program.toLowerCase().replace(/[^a-z0-9]+/g, '-') + '-' + (data.date || 'sem-data') + '.png';
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function populateCoordinationForm(form, data) {
  Object.entries(data.program).forEach(([field, value]) => {
    if (field !== "calls" && field !== "bulletin" && form.elements[field]) {
      form.elements[field].value = field === "time" ? normalizeTimeWithSeconds(value) : value || "";
    }
  });
  setText("last-update", data.updatedAt || "Ainda não salvo");
  renderBulletinInput(data.program.bulletin);
  renderCallInputs(data.program.calls);
}

async function clearPanelToCarousel() {
  const data = await loadData();
  const updated = {
    ...data,
    updatedAt: formatDateTime(new Date()),
    isCleared: true,
    carouselImages: [],
  };

  try {
    await saveData(updated);
    setText("last-update", updated.updatedAt);
  } catch (error) {
    console.error(error);
    setText("last-update", "Painel limpo localmente. Erro ao enviar para a nuvem.");
  }
}

function renderBulletinInput(bulletin) {
  document.querySelectorAll("[data-bulletin-field]").forEach((field) => {
    field.value = bulletin?.[field.dataset.bulletinField] || "";
  });
}

function readBulletinInput() {
  const bulletin = {};
  document.querySelectorAll("[data-bulletin-field]").forEach((field) => {
    bulletin[field.dataset.bulletinField] = field.value.trim();
  });
  return bulletin;
}

function renderCallInputs(calls) {
  const list = document.getElementById("calls-list");
  if (!list) return;
  list.innerHTML = "";
  (calls?.length ? calls : defaults.program.calls).forEach((call) => addCallInput(call));
}

function addCallInput(call = {}) {
  const list = document.getElementById("calls-list");
  const template = document.getElementById("call-template");
  if (!list || !template) return;

  const fragment = template.content.cloneNode(true);
  const row = fragment.querySelector(".call-row");
  const callData = {
    ...defaultCall,
    ...call,
  };

  row.querySelectorAll("[data-call-field]").forEach((field) => {
    field.value = callData[field.dataset.callField] || "";
  });
  row.querySelector("[data-remove-call]").addEventListener("click", () => {
    if (list.querySelectorAll(".call-row").length === 1) {
      row.querySelectorAll("[data-call-field]").forEach((field) => {
        field.value = "";
      });
      return;
    }
    row.remove();
  });
  list.appendChild(fragment);
}

function readCallInputs() {
  return [...document.querySelectorAll(".call-row")].map((row) => {
    const call = {};
    row.querySelectorAll("[data-call-field]").forEach((field) => {
      call[field.dataset.callField] = field.value.trim();
    });
    return call;
  });
}

function initDisplay() {
  const grid = document.getElementById("display-grid");
  if (!grid) return;
  let latestData = loadLocalData();
  let isRendering = false;

  const render = async () => {
    if (isRendering) return;
    isRendering = true;
    
    try {
      const data = await loadData();
      latestData = data;
      const program = data.program;
      document.body.dataset.background = programBackgrounds[program.program] || "";
      setText("display-updated-at", `Última atualização: ${getTimeFromDateTime(data.updatedAt)}`);

      if (!hasSavedData()) {
        grid.innerHTML = `
          <div class="empty-state">
            <div>
              <div class="loader"></div>
              <p>Carregando...</p>
            </div>
          </div>
        `;
        return;
      }

      if (data.isCleared) {
        document.body.dataset.background = "";
        if (!grid.querySelector(".cleared-panel-image")) {
          grid.innerHTML = renderClearedPanel();
        }
        return;
      }

      grid.innerHTML = "";

      const card = document.createElement("article");
      card.className = "display-card program-display-card";
      card.innerHTML = `
        <section class="program-hero" aria-label="Informações do programa">
          <div class="program-summary">
            <span>PRODUÇÃO: ${escapeHtml(program.production || "Não informado")}</span>
            <span aria-hidden="true">|</span>
            <span>BLOCOS: ${escapeHtml(program.blocks || "Não informado")}</span>
          </div>
          ${renderProgramLogo(program.program)}
        </section>
        <section class="countdown-panel" aria-label="Contagem regressiva">
          <span class="card-meta">${escapeHtml(normalizeTimeWithSeconds(program.time) || "--:--:--")}</span>
          <strong id="program-countdown" data-state="${escapeHtml(getCountdownState(program.date, program.time))}">${escapeHtml(getCountdown(program.date, program.time))}</strong>
        </section>
        <div class="display-bottom">
          <div class="calls-stack">
            ${renderBulletin(program.bulletin)}
            <section class="display-section calls-display-section" aria-label="Chamadas">
              <h2>CHAMADAS</h2>
              ${renderCalls(program.calls)}
            </section>
          </div>
          <section class="display-section observations-section" aria-label="Observações">
            <h2>OBSERVAÇÕES</h2>
            <strong>${escapeHtml(program.notes || "Sem observações.")}</strong>
          </section>
        </div>
      `;
      grid.appendChild(card);
    } finally {
      isRendering = false;
    }
  };

  const tick = () => {
    const now = new Date();
    setText("display-date", new Intl.DateTimeFormat("pt-BR", { dateStyle: "full" }).format(now));

    const countdown = document.getElementById("program-countdown");
    if (countdown) {
      countdown.textContent = getCountdown(latestData.program.date, latestData.program.time);
      countdown.dataset.state = getCountdownState(latestData.program.date, latestData.program.time);
    }
  };

  render();
  tick();
  setInterval(render, REMOTE_REFRESH_INTERVAL);
  setInterval(tick, 1000);
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) render();
  });
}

function renderBulletin(bulletin) {
  const hasBulletin = bulletin && bulletin.id;
  if (!hasBulletin) return "";

  return `
    <section class="display-section bulletin-display-section" aria-label="Boletim">
      <h2>BOLETIM</h2>
      <div class="display-call-row bulletin-display-row">
        <span>${escapeHtml(bulletin.id || "-")}</span>
        <strong>${escapeHtml(bulletin.name || "Boletim")}</strong>
        <span>${escapeHtml(formatDurationMinutesSeconds(bulletin.duration) || "--:--")}</span>
        <span>${escapeHtml(bulletin.time || "--:--")}</span>
      </div>
    </section>
  `;
}

function renderClearedPanel() {
  return `
    <section class="cleared-panel-image" aria-label="Painel limpo">
      <img src="assets/painel-limpo.jpg?v=20260521" alt="TV Globo DF" />
    </section>
  `;
}

function renderCalls(calls) {
  const filledCalls = (calls || []).filter((call) => call.id || call.name || call.duration || call.time);
  if (!filledCalls.length) {
    return `<p class="highlight">Nenhuma chamada informada.</p>`;
  }

  return `
    <div class="display-calls">
      ${filledCalls
        .map(
          (call) => `
            <div class="display-call-row">
              <span>${escapeHtml(call.id || "-")}</span>
              <strong>${escapeHtml(call.name || "Chamada")}</strong>
              <span>${escapeHtml(formatDurationMinutesSeconds(call.duration) || "--:--")}</span>
              <span>${escapeHtml(call.time || "--:--")}</span>
            </div>
          `,
        )
        .join("")}
    </div>
  `;
}

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

initCoordination();
initDisplay();
